-- Импорт для MySQL/MariaDB (ISPmanager)
-- Создайте базу данных в ISPmanager, затем выполните этот файл через
-- "Базы данных" -> ваша БД -> "Импорт" (или через phpMyAdmin).

CREATE TABLE IF NOT EXISTS products (
    id INT AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(255) UNIQUE NOT NULL,
    name VARCHAR(255) NOT NULL,
    category VARCHAR(100) NOT NULL,
    badge VARCHAR(100) NULL,
    description TEXT NOT NULL,
    long_description TEXT NULL,
    specs JSON NOT NULL,
    sort_order INT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS services (
    id INT AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(255) UNIQUE NOT NULL,
    name VARCHAR(255) NOT NULL,
    icon VARCHAR(100) NOT NULL,
    short_description TEXT NOT NULL,
    long_description TEXT NULL,
    features JSON NOT NULL,
    sort_order INT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO products (slug, name, category, badge, description, long_description, specs, sort_order) VALUES
('ponton-volna-plyus', 'Понтон «Волна Плюс»', 'Понтоны', 'Хит', 'Универсальный плавучий модуль для причалов и переправ.', 'Понтон «Волна Плюс» — базовое решение для сборки причалов, мостков и плавучих переправ любой конфигурации. Модули изготовлены из прочного полиэтилена НДПЭ, устойчивы к УФ-излучению, перепадам температур и не тонут даже при повреждении корпуса благодаря внутренним воздушным камерам.', '[{"label":"Грузоподъёмность","value":"350 кг/м²"},{"label":"Габариты","value":"500×500 мм"},{"label":"Осадка","value":"6.5 см"},{"label":"Материал","value":"НДПЭ"}]', 1),
('prichal-marina-pro', 'Причал «Марина Про»', 'Причалы', NULL, 'Стационарный причал с алюминиевым настилом.', 'Причал «Марина Про» — стационарная конструкция для яхт-клубов и марин. Алюминиевый каркас обеспечивает долговечность, а настил из лиственницы — комфорт и эстетику. Подходит для установки на реках, водохранилищах и прибрежных акваториях.', '[{"label":"Длина секции","value":"12 м"},{"label":"Ширина","value":"2.4 м"},{"label":"Нагрузка","value":"400 кг/м²"},{"label":"Настил","value":"Лиственница"}]', 2),
('platforma-akvatoriya', 'Платформа «Акватория»', 'Платформы', 'Под заказ', 'Плавучая площадка для кафе, сцен и вертолётов.', 'Платформа «Акватория» — крупногабаритное плавучее сооружение, спроектированное индивидуально под задачу заказчика: летнее кафе, концертная сцена, вертолётная площадка или зона отдыха. Усиленный каркас выдерживает значительные нагрузки и допускает установку дополнительного оборудования.', '[{"label":"Площадь","value":"до 400 м²"},{"label":"Борт","value":"25 т"},{"label":"Крепление","value":"Сваи/якоря"},{"label":"Опции","value":"Ограждение"}]', 3),
('modul-kub-m', 'Модуль «Куб-М»', 'Модули', NULL, 'Универсальный поплавковый куб для сборки любых форм.', 'Модуль «Куб-М» — компактный строительный элемент для быстрой сборки плавучих конструкций произвольной формы: от небольших мостков до крупных платформ. Штифтовое соединение позволяет монтировать и демонтировать конструкцию без спецтехники.', '[{"label":"Габариты","value":"0.5×0.5×0.4 м"},{"label":"Плавучесть","value":"320 кг"},{"label":"Соединение","value":"Штифт"},{"label":"Цвет","value":"8 вариантов"}]', 4),
('ponton-akva-drayv', 'Понтон «Аква-Драйв»', 'Понтоны', NULL, 'Понтон под гидроцикл и катер.', 'Понтон «Аква-Драйв» разработан специально для хранения и спуска гидроциклов и небольших катеров. Система сухого хранения защищает днище судна от обрастания и повреждений, а монтаж занимает всего один день.', '[{"label":"Грузоподъёмность","value":"1000 кг"},{"label":"Габариты","value":"3×5 м"},{"label":"Подъём","value":"Сухое хранение"},{"label":"Монтаж","value":"1 день"}]', 5),
('prichal-yaht-klub', 'Причал «Яхт-Клуб»', 'Причалы', 'Премиум', 'Причальная система для яхт премиум-класса.', 'Причал «Яхт-Клуб» — премиальное решение для престижных марин и частных владений. Оснащён светодиодной подсветкой, надёжными кнехтами и утками, рассчитан на приём крупных яхт длиной до 40 метров.', '[{"label":"Длина","value":"до 40 м"},{"label":"Ширина","value":"3 м"},{"label":"Освещение","value":"LED"},{"label":"Оснастка","value":"Кнехты/утки"}]', 6);

CREATE TABLE IF NOT EXISTS leads (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    phone VARCHAR(50) NOT NULL,
    message TEXT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO services (slug, name, icon, short_description, long_description, features, sort_order) VALUES
('proektirovanie', 'Проектирование', 'PencilRuler', 'Расчёты, 3D-модель и рабочая документация.', 'Разрабатываем проект плавучей конструкции с нуля: инженерные расчёты нагрузок и остойчивости, 3D-визуализация будущего объекта и полный комплект рабочей документации для производства и согласований.', '["Гидростатические расчёты","3D-модель объекта","Рабочие чертежи","Согласование с надзорными органами"]', 1),
('proizvodstvo', 'Производство', 'Factory', 'Изготовление конструкций на собственной верфи.', 'Полный цикл производства на собственной верфи без привлечения субподрядчиков. Контроль качества на каждом этапе — от закупки сырья до финальной сборки готового изделия.', '["Собственная производственная база","Контроль качества на каждом этапе","Работа с НДПЭ и сталью","Изготовление по индивидуальным чертежам"]', 2),
('dostavka', 'Доставка', 'Truck', 'Логистика до объекта в любой регион.', 'Организуем доставку готовых конструкций до места монтажа в любой регион страны — автомобильным, железнодорожным или водным транспортом, включая крупногабаритные и негабаритные грузы.', '["Доставка по всей России","Негабаритные и крупные грузы","Сопровождение груза","Разгрузка на объекте"]', 3),
('montazh-i-yakorenie', 'Монтаж и якорение', 'Wrench', 'Сборка и надёжное закрепление на воде.', 'Собираем конструкцию на месте и выполняем надёжное закрепление на воде с помощью свай, якорей или береговых креплений — с учётом течения, ветровой нагрузки и колебаний уровня воды.', '["Выездная бригада монтажников","Свайное и якорное крепление","Учёт гидрологических условий","Проверка остойчивости после монтажа"]', 4),
('servis', 'Сервис', 'LifeBuoy', 'Гарантийное и сезонное обслуживание.', 'Берём на себя сезонное обслуживание плавучих конструкций: осмотр, мелкий ремонт, консервацию на зиму и подготовку к следующему сезону эксплуатации.', '["Гарантийное обслуживание","Сезонная консервация","Плановые осмотры","Оперативный ремонт"]', 5),
('vvod-v-ekspluatatsiyu', 'Ввод в эксплуатацию', 'Anchor', 'Приёмка и передача документов.', 'Финальный этап — приёмо-сдаточные испытания конструкции, оформление и передача заказчику всей необходимой технической и разрешительной документации.', '["Приёмо-сдаточные испытания","Передача технической документации","Инструктаж по эксплуатации","Гарантийные обязательства"]', 6);